g = [list(map(int, input().split())) for _ in range(5)]
n = int(input())
for _ in range(n):
    r, c = map(int, input().split())
    r -= 1
    c -= 1
    for j in range(5):
        g[r][j] = 1 - g[r][j]
    for i in range(5):
        if i != r:
            g[i][c] = 1 - g[i][c]
for row in g:
    print(*row)
